<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {RouterLink,useRoute,useRouter} from 'vue-router'
import {api,ApiError,date,type Customer,type Order} from '../api'
import {issue,validateBundle,lastBundle,type Bundle} from '../tickets'
import {commandPending,commandBusy,uuidPattern} from '../customerCommands'
import ReservationPending from '../components/ReservationPending.vue'
import TicketQr from '../components/TicketQr.vue'
import {validateWindowStatus,type WindowStatus} from '../admissionWindows'
const windowStatus=ref<WindowStatus|null>(null)
const route=useRoute(),router=useRouter(),id=String(route.params.orderId),customer=ref<Customer|null>(null),bundle=ref<Bundle|null>(null),version=ref(0),error=ref(''),loading=ref(false)
let disposed=false
const visible=computed(()=>customer.value?lastBundle.value?.owner===customer.value.id&&lastBundle.value.bundle.orderId===id?lastBundle.value.bundle:bundle.value:null)
async function load(){if(loading.value)return;loading.value=true;error.value='';bundle.value=null;customer.value=null;windowStatus.value=null;try{if(!uuidPattern.test(id))throw new Error('訂單編號不正確');const c=await api<Customer>('/customer/auth/me');if(disposed)return;customer.value=c;const headers={'X-Expected-Customer-ID':c.id};const b=validateBundle(await api<Bundle>(`/customer/orders/${id}/tickets`,{headers}),id),o=await api<Order>(`/customer/orders/${id}`,{headers});const w=validateWindowStatus(await api<WindowStatus>(`/customer/orders/${id}/admission-window`,{headers}));if(disposed)return;windowStatus.value=w;if(o.id!==id)throw new Error('訂單回覆不完整');version.value=o.version;bundle.value=b;if(lastBundle.value?.owner===c.id&&lastBundle.value.bundle.orderId===id)lastBundle.value={owner:c.id,bundle:b}}catch(e){customer.value=null;bundle.value=null;windowStatus.value=null;error.value=(e as Error).message;if(e instanceof ApiError&&e.status===401)await router.replace('/account/login')}finally{loading.value=false}}
async function collect(){if(!customer.value)return;try{await issue(customer.value,id,version.value);await load()}catch(e){error.value=(e as Error).message}}
onMounted(load);onUnmounted(()=>disposed=true)
</script>
<template><section class="content detail-page"><RouterLink to="/account/orders" class="back-link">← 保票訂單</RouterLink><div class="eyebrow">MY TICKETS</div><h1>你的電子票券。</h1><p>此展示使用免費模擬付款。票券碼等同入場憑證，請勿公開或傳給他人。</p><ReservationPending :customer="customer" @confirmed="load"/><p v-if="error" class="notice error" role="alert">{{error}}</p><button :disabled="loading||commandBusy" @click="load">重新讀取票券</button><template v-if="visible"><div v-if="windowStatus" class="panel"><h2>入場時間</h2><p>台北時間（UTC+8）；開始含、結束不含。</p><p v-if="windowStatus.opensAt&&windowStatus.closesAt">{{date(windowStatus.opensAt)}} 至 {{date(windowStatus.closesAt)}}</p><p>{{windowStatus.state==='UNCONFIGURED'?'場次尚未設定入場時間，暫不接受入場':windowStatus.state==='NOT_OPEN'?'尚未開放入場':windowStatus.state==='CLOSED'?'入場時間已結束':'目前開放入場'}}。持有 QR 仍須現場員工核對；以驗票時的伺服器判定為準。</p></div><p class="muted order-id">訂單 {{visible.orderId}}</p><div v-if="!visible.requestId" class="panel"><p v-if="!visible.eligible">付款或帳號仍需核對，目前不能領取票券。</p><p v-else-if="!visible.issuanceEnabled">電子票券領取尚未開放。</p><button v-else :disabled="loading||commandBusy||!!commandPending" class="primary" @click="collect">領取電子票券</button></div><p v-if="visible.requestId&&!visible.eligible" class="notice warning">原票券已保存，目前付款或帳號需要核對，暫停入場。</p><article v-for="t in visible.tickets" :key="t.id" class="panel"><h2>第 {{t.unit}} 張</h2><p>{{t.state==='ACTIVE'?'尚未使用':t.state==='CHECKED_IN'?'已驗票入場':'已撤銷'}}</p><p class="muted">領取於 {{date(t.createdAt)}}</p><TicketQr v-if="t.state==='ACTIVE'&&visible.eligible" :code="t.code" :unit="t.unit"/><label v-if="t.state==='ACTIVE'">入場票券碼<textarea readonly :value="t.code" :aria-label="'第 '+t.unit+' 張票券碼'" /></label><p v-if="t.changedAt" class="muted">狀態更新 {{date(t.changedAt)}}</p></article></template></section></template>
